mapper.select:
select * from ( SELECT T1.ISSUE_AMT ISSUE_AMT,
,T2.TYPE_6
,T2.TYPE_9 ,T2.TYPE_10 ,T2.TYPE_11 ,T2.TYPE_12
,T4.RATE*100 RATE ,T5.BASIS
,T4.INT_TYPE ,T6.CUSTOMER_NAME financierName ,T7.CUSTOMER_NAME sponsorName,
FPR.recommender recommender, FPR.recommenderName recommenderName,
T1.FINANCIER,T1.SPONSOR FROM FIN_PRODUCT T1
LEFT JOIN ( SELECT FPR.FINPROD_ID, group_concat(FPR.RECOMMENDER order by FPR.RECOMMENDER separator '，') recommender, group_concat(MCP.COUNTER_NAME order by FPR.RECOMMENDER separator '，') recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = T1.FINPROD_ID
left join FIN_PRODUCT_TYPE T2 ON T2.FINPROD_ID = T1.FINPROD_ID left join FIN_CASH_INFO T3 ON T3.FINPROD_ID = T1.FINPROD_ID
AND T3.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T3.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
left join FIN_RATE_INFO T4 ON T4.CASH_ID = T3.CASH_ID AND T4.EFF_DATE = T1.VDATE LEFT JOIN FIN_CASH_CALC_RULE T5 ON T5.CASH_ID = T3.CASH_ID and T5.EFF_DATE = T1.VDATE LEFT JOIN MST_CUSTOMER_INFO T6 ON T6.CUSTOMER_ID = T1.FINANCIER LEFT JOIN MST_CUSTOMER_INFO T7 ON T7.CUSTOMER_ID = T1.SPONSOR )T
AND (T.FINPROD_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%') or T.FINPROD_NAME like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%'))
AND T.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T.CCY = #{ccy,jdbcType=VARCHAR}
AND T.TYPE_6 in
#{item}
AND T.TYPE_9 in
#{item}
AND T.TYPE_10 in
#{item}
AND T.TYPE_11 in
#{item}
AND T.TYPE_12 in
#{item}
AND T.VDATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
AND T.VDATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
AND T.MDATE >= STR_TO_DATE(#{mdateStart},'%Y-%m-%d')
AND T.MDATE <= STR_TO_DATE(#{mdateEnd},'%Y-%m-%d')
AND T.FINANCIER = #{financier,jdbcType=VARCHAR}
AND T.SPONSOR = #{sponsor,jdbcType=VARCHAR}

SELECT T1.ISSUE_AMT ISSUE_AMT,
,T3.TYPE_6, T3.TYPE_7,
T3.TYPE_9, T3.TYPE_10, T3.TYPE_11, T3.TYPE_12,
T4.ASSET_SOURCE, T4.ASSET_PROVIDER, T4.ASSET_SOURCE_UNIT, T4.LOAD_BANK, T4.SETTLE_DAYS, t2.INVEST_NATURE, T4.PROJ_INVEST_INDUSTRY, T4.PROJ_INVEST_INDUSTRY2, T4.CASH_OUT_NO CASH_OUT_NO, T5.BUYOUT_RATE*100 BUYOUT_RATE, T.PFLSH pflsh, T.HAP_CREDIT_AMT hapCreditAmt, T.CREDIT_FLAG creditFlag, T4.ACTUAL_CREDIT_PROVID actualCreditProvid, T1.FINANCIER financier, T1.SPONSOR sponsor, T6.REP_ASSET_TYPE, T4.TRIAL_NO, T1.CONTRACT_NO, T1.INVEST_ADVISER FROM FIN_PRODUCT T1 LEFT JOIN ( SELECT B.FINPROD_ID, A.CREDIT_FLAG, A.PFLSH, A.HAP_CREDIT_AMT , A.CUSTOMER_ID FROM ( select @rownum:=@rownum+1 rownum,a.CREDIT_FLAG,a.PFLSH,a.HAP_CREDIT_AMT,a.CUSTOMER_ID if(@CUSTOMER_ID=a.CUSTOMER_ID,@rank:=@rank+1,@rank:=1) as RN, @CUSTOMER_ID:=a.CUSTOMER_ID from(SELECT * from CREDIT_LINES order by CUSTOMER_ID,VDATE)a, (select @rownum:=0,@CUSTOMER_ID:=null,@rank:=0)b ) A LEFT JOIN CREDIT_ASSETPOOL_DETAIL B ON B.SEQNO = A.CUSTOMER_ID where A.RN = 1 ) T ON (T.FINPROD_ID = T1.FINPROD_ID OR T.CUSTOMER_ID = T1.FINPROD_ID) LEFT JOIN FIN_PRODUCT_ADD T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T3 ON T3.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT_BUYOUT_RATE T5 ON T5.FINPROD_ID = T1.FINPROD_ID AND T5.EFF_DATE = T1.VDATE LEFT JOIN REP_ASSET_DEPT T6 on T1.FINPROD_ID = T6.REP_FINPROD_ID
T1.FINPROD_ID = #{finprodId}
T1.FINPROD_MARKET_ID = #{finprodMarketId}
